# owner: platform
"""Seating charts: students sorted by last name."""

from typing import List

from rosterkit.models import Student

def _check_inputs(
    students: List[Student],
    seats: int
) -> None:
    if seats <= 0:
        raise ValueError("seats must be positive")
    if not students:
        raise ValueError("no students to seat")

def _sort_key(student: Student) -> tuple:
    return (
        student.last_name.lower(),
        student.first_name.lower()
    )

def _render_row(number: int, group: List[Student]) -> str:
    names = [item.display_name for item in group]
    return f"Row {number}: " + " | ".join(names)

def _split_rows(ordered: list, seats: int) -> list:
    return [
        ordered[start:start + seats]
        for start in range(0, len(ordered), seats)
    ]

def seating_rows(
    students: List[Student],
    seats: int
) -> List[str]:
    """One text line per row of seats."""
    _check_inputs(students, seats)
    ordered = sorted(students, key=_sort_key)
    rows = _split_rows(ordered, seats)
    return [
        _render_row(index, group)
        for index, group in enumerate(rows, 1)
    ]

