# owner: platform
import unittest

from rosterkit.models import Student
from rosterkit.seating import seating_rows

def make_student(last, first):
    return Student(last + first, last, first, "A")

class SeatingTests(unittest.TestCase):
    def test_sorted_and_split_into_rows(self):
        found = seating_rows(
            [
                make_student("Halloway", "Juno"),
                make_student("Zane", "Ola"),
                make_student("Dunmere", "Piet")
            ],
            2
        )
        self.assertEqual(
            found,
            [
                "Row 1: Dunmere, Piet | Halloway, Juno",
                "Row 2: Zane, Ola"
            ]
        )

    def test_same_last_name_sorts_by_first(self):
        found = seating_rows(
            [
                make_student("Lee", "Zoe"),
                make_student("Lee", "Amy")
            ],
            5
        )
        expect = ["Row 1: Lee, Amy | Lee, Zoe"]
        self.assertEqual(found, expect)

    def test_sorting_ignores_case(self):
        found = seating_rows(
            [
                make_student("beck", "Al"),
                make_student("Adams", "Bo")
            ],
            1
        )
        self.assertEqual(found[0], "Row 1: Adams, Bo")

    def test_bad_seat_counts_raise(self):
        pupils = [make_student("Lee", "Amy")]
        for seats in (0, -3):
            with self.assertRaises(ValueError):
                seating_rows(pupils, seats)

    def test_no_students_raises(self):
        with self.assertRaises(ValueError):
            seating_rows([], 3)
